import java.util.*;class Student{private final String name,department;private final List<NotificationChannel> channels=new ArrayList<>();public Student(String n,String d){if(n==null||n.trim().isEmpty()||d==null||d.trim().isEmpty())throw new IllegalArgumentException();name=n;department=d;}public String getName(){return name;}public String getDepartment(){return department;}public void addPreferredChannel(NotificationChannel c){if(c==null)throw new IllegalArgumentException();if(!channels.contains(c))channels.add(c);}public List<NotificationChannel> getPreferredChannels(){return Collections.unmodifiableList(channels);}}
interface NotificationChannel{String send(Student s,Notice n);}class EmailChannel implements NotificationChannel{public String send(Student s,Notice n){return "[Email → "+s.getName()+"] "+n.getTitle();}}class SmsChannel implements NotificationChannel{public String send(Student s,Notice n){return "[SMS → "+s.getName()+"] "+n.getTitle();}}class AppChannel implements NotificationChannel{public String send(Student s,Notice n){return "[App → "+s.getName()+"] "+n.getTitle();}}
class Notice{private final String title;private final List<String> targets;public Notice(String t,List<String> d){if(t==null||t.trim().isEmpty()||d==null||d.isEmpty())throw new IllegalArgumentException("At least one target department is required");title=t;targets=new ArrayList<>();for(String x:d)if(x!=null&&!x.trim().isEmpty()&&!targets.contains(x))targets.add(x);if(targets.isEmpty())throw new IllegalArgumentException("At least one target department is required");}public String getTitle(){return title;}public List<String> getTargetDepartments(){return Collections.unmodifiableList(targets);}}
public class NoticeBoard{private final List<Student> students=new ArrayList<>();public void registerStudent(Student s){if(s==null)throw new IllegalArgumentException();students.add(s);}public List<String> postNotice(Notice n){if(n==null)throw new IllegalArgumentException();List<String> out=new ArrayList<>();for(Student s:students)if(n.getTargetDepartments().contains(s.getDepartment()))for(NotificationChannel c:s.getPreferredChannels())out.add(c.send(s,n));return out;}}
